import React from 'react';
import './Footer.css';

const Footer = () => {
  return (
    <footer className="site-footer">
      <div className="footer-container">
        <div className="footer-info">
          <h3>MMD ANAALYTICS INDIA PRIVATE LIMITED</h3>
          <p>📍 Location: Ranchi, Jharkhand<br></br>
          📧 Email: admin@mmdai.in<br></br>📞 Phone: 6204958442<br></br><small>🏢 Office: 202, Sulakshana by Maurya Homes, Argora Kathal More Road, beside Dayal Petrol Pump, Kathal More, Ranchi</small><br></br></p>
        </div>
        <div className="footer-links">
          <p>&copy; 2024 MMD ANAALYTICS. All rights reserved.</p>
        </div>
      </div>
    </footer>
  );
};

export default Footer;
